def run(*cmd):
    return subprocess.run(cmd, capture_output=True, text=True)

if not (os.path.isdir("app") and os.path.isfile("AGENTS.md")):
    sys.exit("Run this from the root of the commercial-operations-ai repository (the folder that contains app/ and AGENTS.md).")
if run("git", "rev-parse", "--is-inside-work-tree").returncode != 0:
    sys.exit("This folder is not a git repository.")

r = run("git", "checkout", "-b", BRANCH)
print(("Created branch " + BRANCH) if r.returncode == 0 else ("Branch exists or could not be created, staying on the current branch: " + r.stderr.strip()))

for f in DELETE:
    if os.path.exists(f):
        os.remove(f); print("deleted", f)

data = base64.b64decode("".join(PAYLOAD))
with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as t:
    names = t.getnames()
    for m in t.getmembers():
        if m.name.startswith("/") or ".." in m.name.split("/"):
            sys.exit("Unsafe path in installer: " + m.name)
    t.extractall(".")
print("wrote", len(names), "files")
try:
    os.remove(os.path.abspath(__file__))  # the installer deletes itself so it is not committed
except OSError:
    pass
run("git", "add", "-A")
print()
print("Done. Next:")
print("  1) cd app && npm ci && npm test        (expect 123 passed)")
print("  2) cd ../ai-service && python3 -m venv .venv && . .venv/bin/activate && pip install -e '.[dev]' && python -m pytest   (expect 34 passed)")
print("  3) git commit -m 'Replace Groq with OpenRouter, add Python AI service, new UI' && git push -u origin " + BRANCH)
